def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    if platform.system() == "Windows":
        cmd = tuple(c.replace("\\", "\\\\") for c in cmd)
    if cmd[0].startswith("#!"):
        cmd = ("python", "-c", cmd[0][2:], *cmd[1:])
    return cmd

