def lfu_cache(maxsize=128, typed=False):
    from collections import OrderedDict

    class LFUCache:
        def __init__(self, maxsize):
            self.maxsize = maxsize
            self.hits = {}
            self.misses = {}
            self.queue = OrderedDict()

        def __getitem__(self, key):
            entry = self.queue.pop(key)
            self.queue[key] = entry
            return entry

        def __setitem__(self, key, value):
            self.queue[key] = value

        def __delitem__(self, key):
            del self.queue[key]

        def get(self, key, default=None):
            try:
                return self.queue[key]
            except KeyError:
                return default

        def __contains__(self, key):
            return key in self.queue

        def pop(self, key, default=None):
            try:
                value = self.queue.pop(key)
            except KeyError:
                return default
            else:
                return value

        def clear(self):
            self.hits.clear()
            self.misses.clear()
            self.queue.clear()

        def get_hits(self):
            return len(self.hits)

        def get_misses(self):
            return len(self.misses)

    def decorator(fn):
        cache = LFUCache(maxsize)

        # Wrap the function with a new function that checks the cache first
        def wrapper(*args, **kwargs):
            key = (args, tuple(kwargs.items()))
            if key in cache:
                # Cache hit
                cache.hits[key] = cache.hits.get(key, 0) + 1
                return cache[key]
            else:
                # Cache miss
                cache.misses[key] = cache.misses.get(key, 0) + 1
                value = fn(*args, **kwargs)
                cache[key] = value
                return value

        return wrapper

    return decorator

