def extostr(e, max_level=30, max_path_level=5):
    """
    Format an exception.
    :param e: Any exception instance.
    :type e: Exception
    :param max_level: Maximum call stack level (default 30)
    :type max_level: int
    :param max_path_level: Maximum path level (default 5)
    :type max_path_level: int
    :return The exception readable string
    :rtype str
    """
    if isinstance(e, Exception):
        lines = ["[%s]" % (e.__class__.__name__)]
        tbinfo = traceback.extract_tb(e.__traceback__, max_level)
        for line in tbinfo:
            lines.append("  File %s" % (line[0]))
            sline = line[1]
            module_name = line[2]
            if '<module>' in module_name:
                continue
            elif module_name is not None:
                sline = "%s:%s" % (module_name, sline)
            else:
                if line[0].endswith(".egg/site-packages/FandomParser/__init__.py"):
                    sline = "%s/%s" % (line[0].split("/")[-2], sline)
                else:
                    sline = line[0]
            lines.append("    File %s" % (sline))
            if module_name is not None:
                sline = "%s.%s" % (module_name, line[2])
            elif line[2] is not None:
                sline = line[2]
            else:
                sline = line[0]
            lines.append("      %s" % (sline))
            lines.append("  line %s" % (line[1]))

        for name, value in sorted(e.__dict__.items()):
            lines.append("  %s = %s" % (name, value))
        lines.append("  with traceback:")
        lines.append("    %s" % (e))

        return "\n".join(lines).strip()

def append_text_to_file(file_name, text_buffer, encoding, overwrite=False):
    file_path = os.path.abspath(file_name)

    if not os.path.isdir(os.path.dirname(file_path)):
        raise FileNotFoundError(f"Directory does not exist: {file_path}")

    if overwrite and os.path.isfile(file_path):
        os.remove(file_path)

    with open(file_path, "a+", encoding=encoding) as output_file:
        output_file.write(text_buffer)

    return os.path.getsize(file_path)

