def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    seen = set()
    ordered = []
    for cls in classes:
        if cls not in seen:
            seen.add(cls)
            ordered.append(cls)
            for b in minimalBases(cls.__bases__):
                if b not in seen:
                    seen.add(b)
                    ordered.append(b)
    return ordered

def minimalBases(classes):
    seen = set()
    for cls in classes:
        if cls not in seen:
            seen.add(cls)
            for b in minimalBases(cls.__bases__):
                yield b
    yield cls

def namesAndDescriptions(self, all=False):
    """Return attribute names and descriptions defined by interface."""
    # Check if the "all" argument is a boolean value
    if not isinstance(all, bool):
        raise TypeError("Argument 'all' must be a boolean value")

    # Get the names and descriptions of all attributes defined by the interface
    if all:
        names, descriptions = [], []
        for name, value in self.__dict__.items():
            if isinstance(value, InterfaceAttribute):
                names.append(name)
                descriptions.append(value.description)
        return names, descriptions

    # Get the names and descriptions of all non-private attributes defined by the interface
    else:
        names, descriptions = [], []
        for name, value in self.__dict__.items():
            if name.startswith("_") or not isinstance(value, InterfaceAttribute):
                continue
            names.append(name)
            descriptions.append(value.description)
        return names, descriptions

