def difference(d1, d2, level=-1):
    """
    Return a dictionary with items from *d1* not contained in *d2*.
    """

    # Set the maximum depth of recursion
    if level == -1:
        max_level = None
    else:
        max_level = level

    # Iterate through the elements of d1
    for element in d1:
        if element not in d2:
            # If the element is not in d2, add it to the difference dictionary
            difference_dict[element] = d1[element]
        elif isinstance(d1[element], dict) and isinstance(d2[element], dict):
            # If the element is a dictionary, recursively call difference with a deeper max level
            difference_dict[element] = difference(d1[element], d2[element], max_level)
        elif d1[element] != d2[element]:
            # If the element is not equal to the corresponding element in d2, add it to the difference dictionary
            difference_dict[element] = d1[element]

    return difference_dict

def difference(d1, d2, level=-1):
    if level == -1:
        return {k: v for k, v in d1.items() if k not in d2 or (isinstance(v, dict) and difference(v, d2[k]))}
    else:
        return {k: v for k, v in d1.items() if k not in d2 or (isinstance(v, dict) and difference(v, d2[k], level - 1))}

def difference(d1, d2, level=-1):
    """
    Return a dictionary with items from *d1* not contained in *d2*.
    """
    if level > 0:
        result = {}
        for k, v in d1.items():
            if k not in d2 or v != d2[k]:
                if isinstance(v, dict):
                    result[k] = difference(v, d2.get(k, {}), level - 1)
                else:
                    result[k] = v
        return result

def difference(d1, d2, level=-1):
    """
    Return a dictionary with items from `d1` not contained in `d2`.
    """
    diff = {}
    for key, value in d1.items():
        if type(value) != dict or (level != -1 and d2.get(key) != value):
            diff[key] = value
        elif level != 0:
            sub_diff = difference(value, d2.get(key, {}), level-1)
            if sub_diff:
                diff[key] = sub_diff
    return diff

def difference(d1, d2, level=-1):
    """
    Return a dictionary with items from `d1` not contained in `d2`.

    `level` sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in `d1` and `d2` but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    `d1` and `d2` remain unchanged. However, `d1` or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument `level`.
    """
    if level <= 0:
        return {k: v for k, v in d1.items() if k not in d2 or d1[k] != d2[k]}
    else:
        output = {}
        for k in d1:
            if k not in d2 or d1[k] != d2[k]:
                output[k] = d1[k]
            elif isinstance(d1[k], dict) and isinstance(d2[k], dict):
                subdiff = difference(d1[k], d2[k], level=level - 1)
                if subdiff:
                    output[k] = subdiff
        return output

def fill(self, coord, weight=1):
    """
    Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if coord[0] >= 0 and coord[0] < len(self.edges):
        if coord[1] >= 0 and coord[1] < len(self.edges):
            self.values[coord[0]][coord[1]] += weight
            return True
    return False

def fill(self, coord, weight=1):
    """
    Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if len(coord) != self.ndim:
        raise ValueError("Coord must have length equal to the number of dimensions for this histogram")
    if weight < 0:
        raise ValueError("Weight must be non-negative")

    for i in range(self.ndim):
        if coord[i] < self.edges[i][0] or coord[i] >= self.edges[i][-1]:
            # Coordinate outside the histogram edge
            return
    for i in range(self.ndim):
        # Find the bin that this coordinate belongs to
        if coord[i] < self.edges[i][-1]:
            bin_i = np.searchsorted(self.edges[i], coord[i], side="left")
            break
    else:
        # All coordinates were outside of the histogram edge
        return

    # Increment the bin count by the given weight
    self.bins[bin_i] += weight

