def generate_default_observer_schema(app):
    """
    Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.
    :type app: krake.data.kubernetes.Application
    :rtype: dict
    """
    default_schema = {
        resource_name: {
            'spec': {},
            'status': {}
        }
        for resource_name in app.spec.manifest.keys()
    }

    for resource_name in app.spec.manifest.keys():
        manifest = app.spec.manifest[resource_name]
        if 'observer_schema' in manifest:
            default_schema[resource_name]['spec'] = {**manifest['observer_schema']['spec']}
            default_schema[resource_name]['status'] = {**manifest['observer_schema']['status']}
        else:
            resource_type = manifest['kind']
            if resource_type in ['*', 'v1/RS', 'v1/Deployment', 'apps/v1/Deployment', '*', 'v1/Sv', 'v1/Service']:
                default_schema[resource_name]['spec'] = {'desired_replicas': {'default': 1, 'doc': 'number of desired replicas'}, 'running_replicas': {'default': 0, 'doc': 'number of running replicas'}, 'ready_replicas': {'default': 0, 'doc': 'number of ready replicas'}, 'restart_count': {'default': 0, 'doc': 'number of restarts'}}
                default_schema[resource_name]['status'] = {'ready': {'default': False, 'doc': 'resource status'}}
            elif resource_type in ['*', 'db1/Pwd', 'db1/Pwd', 'db1/User', 'db1/Db', '*', 'db1/Ing', 'db1/Snapshot']:
                default_schema[resource_name]['spec'] = {'status': {'default': False, 'doc': 'object status'}}
            elif resource_type in ['*', '*', 'v1/POD', 'core/v1/Pod']:
                default_schema[resource_name]['spec'] = {'ip': {'doc': 'object ip'}, 'hostname': {'doc': 'object hostname'}, 'container_statuses': {'doc': 'container statuses'}}
                default_schema[resource_name]['status'] = {'hostname': {'doc': 'object hostname'}, 'container_statuses': {'doc': 'container statuses'}}

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    default_observer_schema = {}
