def format(self, sql, params):
    if not isinstance(params, (dict, list)):
        raise TypeError("Invalid parameter type: should be dict or list, got {}".format(type(params)))

    if isinstance(params, dict):
        if self.in_style != self.PARAM_NAMED:
            raise ValueError("Invalid parameter dictionary for {} style parameters".format(self.in_style))
        params = list(params.items())
    elif isinstance(params, list):
        if self.in_style != self.PARAM_ORDINAL:
            raise ValueError("Invalid parameter list for {} style parameters".format(self.in_style))
    else:
        raise ValueError("Unsupported parameter type: {}".format(type(params)))

    db_params = {
        self.PARAM_MARKER: []  # type: Union[List[Any], Dict[str, Any]]
    }

    # Replace the in-style parameters with out-style parameters
    for param in params:
        if isinstance(param, tuple):
            # Named parameter
            if self.in_style != self.PARAM_NAMED:
                raise ValueError("Cannot use named parameters as in-style parameters")
            if not isinstance(param[0], str):
                raise ValueError("Invalid parameter name: should be str, got {}".format(type(param[0])))
            db_params[param[0]] = param[1]
            param = self.PARAM_MARKER
        else:
            # Ordinal parameter
            if self.in_style != self.PARAM_ORDINAL:
                raise ValueError("Cannot use ordinal parameters as in-style parameters")
        sql = sql.replace(param, self.PARAM_MARKER, 1)
        db_params[self.PARAM_MARKER].append(param)

    return sql, db_params

def format(self, sql, params):
    """
    Convert the SQL query to use the out-style parameters instead of
    the in-style parameters.

    :param sql: the SQL query
    :type sql: str or bytes
    :param params: the set of in-style parameters
    :type params: dict or list
    :return: the formatted SQL query and the set of converted out-style parameters
    :rtype: tuple
    """
    # Raise an error if the input is invalid
    if not isinstance(sql, (str, bytes)):
        raise ValueError("Invalid input type for sql")
    if not isinstance(params, (dict, list, tuple)):
        raise ValueError("Invalid input type for params")

    # Parse the SQL query to replace in-style parameters with out-style parameters
    out_sql = sql
    out_params = {}
    if params:
        # Parse the in-style parameters
        if isinstance(params, dict):
            in_params = params
        else:
            in_params = {str(i + 1): p for i, p in enumerate(params)}

        # Replace in-style parameters with out-style parameters
        for param in in_params:
            if isinstance(param, str):
                param = "@" + param
            out_sql = out_sql.replace(param, "@" + str(in_params[param]))
            out_params[param] = in_params[param]

    return out_sql, out_params

def format(self, sql: AnyStr, params: Union[Dict[Union[str, int], Any], Sequence[Any]]) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
    """
    Convert the SQL query to use the out-style parameters instead of
    the in-style parameters.

    *sql* (:class:`str` or :class:`bytes`) is the SQL query.

    *params* (:class:`~collections.abc.Mapping` or :class:`~collections.abc.Sequence`)
    contains the set of in-style parameters. It maps each parameter
    (:class:`str` or :class:`int`) to value. If :attr:`.SQLParams.in_style`
    is a named parameter style. then *params* must be a :class:`~collections.abc.Mapping`.
    If :attr:`.SQLParams.in_style` is an ordinal parameter style, then
    *params* must be a :class:`~collections.abc.Sequence`.

    Returns a :class:`tuple` containing:

    - The formatted SQL query (:class:`str` or :class:`bytes`).

    - The set of converted out-style parameters (:class:`dict` or :class:`list`).
    """
    # Check if the in-style parameters are valid
    if not params:
        return sql, {}

    # Convert in-style parameters to out-style parameters
    formatted_params = {}
    if isinstance(params, dict):
        # Named parameter style
        if self.in_style == ParameterStyle.named:
            formatted_params = {k: v for k, v in params.items()}
        # Ordinal parameter style
        else:
            for i, v in enumerate(params.values()):
                formatted_params[str(i + 1)] = v
    else:
        # Ordinal parameter style
        if self.in_style == ParameterStyle.named:
            raise ValueError("Invalid parameter type for named parameter style")
        else:
            for i, v in enumerate(params):
                formatted_params[str(i + 1)] = v

    # Replace the in-style parameter placeholders with out-style parameter placeholders
    sql = sql.replace(self.in_style.placeholder, self.out_style.placeholder)

    return sql, formatted_params

def formatmany(self, sql, many_params):
    formatted_sql = []
    out_style_params = []
    for params in many_params:
        if self.in_style == 'named':
            formatted_sql.append(self._format_named_params(sql, params))
            out_style_params.append(self._convert_named_params_to_out_style(params))
        else:
            formatted_sql.append(self._format_ordinal_params(sql, params))
            out_style_params.append(list(params))
    return ''.join(formatted_sql), out_style_params

