def check_digests_present_and_used(self, manifest_files, digests_used):
    """
    Check all digests in manifest that are needed are present and used.

    :param manifest_files: List of files in the manifest
    :param digests_used: Set of digests used in the analysis
    """
    # Check if all required digests are present in the manifest
    for digest in digests_used:
        if not any(digest in file.digests for file in manifest_files):
            raise ValueError(f"Required digest {digest} is not present in the manifest!")

    # Check if all digests in the manifest are used
    for file in manifest_files:
        if file.digests:
            for digest in file.digests:
                if digest not in digests_used:
                    raise ValueError(f"Digest {digest} is present in manifest but is not used!")

