    # First, check that the fixity block is a dictionary
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block is not a dictionary")

    # Next, check that all file keys in the fixity block are present in the manifest
    for file_key in fixity.keys():
        if file_key not in manifest_files:
            raise ValueError("File '{}' listed in fixity block is not present in manifest".format(file_key))

    # Finally, check that all hashes in the fixity block are valid
    for file_key, file_hashes in fixity.items():
