            if hash_type not in ("md5", "sha256") and hash_value not in fixity[file]:
                raise ValueError(f"Missing hash value for hash type '{hash_type}' for file '{file}'")

    # Check if the fixity block includes any unknown or invalid hash values
    for file, fixity_info in fixity.items():
        for hash_type, hash_value in fixity_info.items():
