def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Check if the input is a list of commands
    if not isinstance(commands, list):
        raise TypeError("'commands' must be a list of strings")

    # Check if the input is a list of args
    if not isinstance(args, list):
        raise TypeError("'args' must be a list of strings")

    # Check if the input cwd is valid
    if cwd is not None and not isinstance(cwd, str):
        raise TypeError("'cwd' must be a string or None")

    # Check if the input env is valid
    if env is not None and not isinstance(env, dict):
        raise TypeError("'env' must be a dictionary or None")

    # Check if the input verbose and hide_stderr are valid
    if not isinstance(verbose, bool):
        raise TypeError("'verbose' must be a boolean")
    if not isinstance(hide_stderr, bool):
        raise TypeError("'hide_stderr' must be a boolean")

    # Convert the command and args to a string
    if len(commands) == 1:
        command = commands[0]
    else:
        command = " ".join(commands)

    # Set up the subprocess arguments
    subprocess_args = {
        "args": args,
        "cwd": cwd,
        "env": env,
        "text": verbose,
        "stderr": subprocess.PIPE if hide_stderr else None,
    }

    # Run the subprocess and check the status code
    result = subprocess.run(command, **subprocess_args)
    if result.returncode != 0:
        raise subprocess.CalledProcessError(
            returncode=result.returncode,
            cmd=command,
            output=result.stderr.decode("utf-8"),
        )

    # Return the subprocess output
    return result.stdout.decode("utf-8")

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """
    Call the given command(s).

    :param commands: the command(s) to run
    :type commands: list

    :param args: the arguments to pass to the command
    :type args: list

    :param cwd: the working directory in which to run the command
    :type cwd: str

    :param verbose: whether to print the command output to stdout
    :type verbose: bool

    :param hide_stderr: whether to hide the command error output
    :type hide_stderr: bool

    :param env: the environment variables to set for the command
    :type env: dict

    Raises:
        ProgramError: if an error occurred while running the command
    """
    if not commands:
        raise ValueError("No commands provided")
    if not args:
        args = []
    if not cwd:
        cwd = os.getcwd()
    if not env:
        env = os.environ.copy()
    if not isinstance(commands, list):
        commands = [commands]
    for command in commands:
        if not isinstance(command, str):
            raise ValueError("Invalid command type, should be list of str")
    try:
        if hide_stderr:
            stderr = subprocess.DEVNULL
        else:
            stderr = subprocess.PIPE
        process = subprocess.Popen([*commands, *args], stdout=subprocess.PIPE, stderr=stderr, cwd=cwd, env=env)
        stdout, stderr = process.communicate()
        if process.returncode != 0:
            raise ProgramError(f"Error running command: {command}")
        if verbose:
            print(stdout.decode("utf-8"))
    except Exception as e:
        raise ProgramError(f"Error running command: {command}") from e

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """
    Call the given command(s).

    :param commands: the command to run (single command or a list of commands)
    :param args: the arguments for the command(s)
    :param cwd: the working directory for the command
    :param verbose: whether to print the command output
    :param hide_stderr: whether to hide stderr output
    :param env: the environment variables for the command
    """
    if not isinstance(commands, list):
        commands = [commands]
    if not isinstance(args, list):
        args = [args]
    try:
        for cmd in commands:
            if verbose:
                print("Calling command:", cmd)
            p = subprocess.Popen(cmd, cwd=cwd, shell=True, stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=(subprocess.STDOUT if hide_stderr else subprocess.PIPE))
            output, _ = p.communicate(input=args, env=env)
            if verbose:
                print("Command output:", output.decode())
            if p.returncode != 0:
                raise CommandError("Command failed with exit status {}".format(p.returncode))
    except subprocess.CalledProcessError as e:
        raise CommandError("Command failed with exit status {}".format(e.returncode))

