    """
    Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.

    :param version: Version string
    :return: Next version identifier
    """
    if version == "1.0.0":
        return "1.1.0"
    elif version == "1.1.0":
        return "1.2.0"
    elif version == "1.2.0":
        return "2.0.0"
    else:
        raise ValueError("Invalid version string")

def next_version(version) -> str:
    """
    Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if version.isdigit():
        if version[0] == '0':
            return f"{int(version) + 1}"
        else:
            return f"{int(version) + 1}"
    else:
        return f"{version[1:]}{int(version[0]) + 1}"

