        types = [f for f in types if f.endswith("0=*.nam")]
        if not types:
            return "root"
        else:
            return "object"
    except FileNotFoundError:
        return "file"
    except IsADirectoryError:
        return "file"

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    try:
        if "0=*" in os.listdir(path):
            return 'object'
        else:
            return 'root'
    except FileNotFoundError:
        return 'error: directory does not exist'
    except OSError:
        return 'error: unable to list files in directory'

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    try:
        if os.path.isdir(path) and any("0=*" in line for line in os.listdir(path)):
            return "root"
        elif os.path.isdir(path):
            return "object"
        elif os.path.isfile(path) and "0=*" in open(path, "r").readline():
            return "object"
        else:
            return "file"
    except (OSError, IOError) as e:
        return "file"

def amend_bzparams(self, params: Dict, bug_ids: List[int]) -> None:
    """Amend the Bugzilla params.

    :param params: A dict of parameters to be amended.
    :param bug_ids: A list of bug IDs to be added/removed from the `params` dict.
    """
    # Check if any of the parameters are not valid
    invalid_params = [k for k in params.keys() if k not in self.allowed_params]
    if invalid_params:
        raise ValueError(f"Invalid params: {invalid_params}. Allowed params: {self.allowed_params}")

    # Add/remove bugs from the `params` dict
    for bug_id in bug_ids:
        if bug_id in self.bug_ids:
            params[self.bug_param_name].append(str(bug_id))
        else:
            params[self.bug_param_name].remove(str(bug_id))

    # Update the `bug_ids` list with the new list of bug IDs
    self.bug_ids = bug_ids

    # Check if the number of bugs in the `params` dict matches the number of bug IDs
    if len(params[self.bug_param_name]) != len(self.bug_ids):
        raise ValueError(f"Number of bugs in the `params` dict ({len(params[self.bug_param_name])}) does not match the number of bug IDs ({len(self.bug_ids)})")

def amend_bzparams(self, params, bug_ids):
    """
    Amend the Bugzilla params
    :param params: A dictionary of Bugzilla params
    :param bug_ids: A list of Bugzilla bug IDs
    :return: A dictionary of amended Bugzilla params
    """
    if not isinstance(bug_ids, list):
        raise ValueError("Bug IDs must be a list")

    for bug_id in bug_ids:
        if not isinstance(bug_id, int):
            raise ValueError(f"Invalid bug ID: {bug_id}")

    for param in params:
        if not param.startswith("bz_"):
            raise ValueError(f"Invalid param: {param}")

    params["bug_id"] = ",".join(str(bug_id) for bug_id in bug_ids)

    return params

