def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    for bug_id in bug_ids:
        bug = self.get(bug_id)
        if bug:
            for param, value in params.items():
                if param not in self.valid_bzparams:
                    raise ValueError(f"Invalid parameter '{param}'")
                if param in bug.prior_params:
                    bug.params[param] = value
            bug.update()

def deep_merge_nodes(nodes):
    result = []
    for node in nodes:
        key = node[0]
        value = node[1]
        if not isinstance(value, ruamel.yaml.nodes.MappingNode):
            # Restrict the merge to nodes that are mapping nodes.
            result.append(node)
            continue
        existing_node = next((n for n in result if n[0] == key), None)
        if existing_node is None:
            # No existing node with the given key, so we can simply append the
            # node as is.
            result.append(node)
            continue
        for subkey, subvalue in value.value:
            subexisting_node = next((n for n in existing_node[1].value
                                      if n[0] == subkey), None)
            if subexisting_node is None:
                # No existing subnode with the given subkey, so we can simply
                # append the subnode as is.
                existing_node[1].value.append((subkey, subvalue))
            else:
                # Merge the subvalue with the existing subnode.
                subexisting_node[1].value += subvalue.value
    return result

