def bash_completion():
    """ Returns a bash completion script for the borgmatic command. Produce this by introspecting
    borgmatic's command-line argument parsers. """

    import re
    import subprocess

    def main():
        process = subprocess.Popen(
            "rod --help | grep -Eo '--[a-zA-Z_-]*=.*'", shell=True, stdout=subprocess.PIPE
        )
        stdout, _ = process.communicate()
        options = stdout.decode().splitlines()

        completions = {}

        prefix = ""

        for option in options:
            match = re.match(r"--[a-zA-Z_-]*", option)
            if match:
                completions[match.string[2:]] = option[2:]

        def print_completions(prefix, choices):
            completions = sorted(choices)
            if len(completions) == 1:
                print(f"{prefix}{completions[0]}")
            elif len(completions) > 1:
                for choice in completions:
                    print(f"{prefix}{choice}")

        print_completions(prefix, completions.keys())

    if __name__ == "__main__":
        main()

def parse_subparser_arguments(unparsed_arguments, subparsers):
    """
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    """

    # Create a dict mapping from subparser name to a list of unparsed arguments
    unparsed_arguments_dict = {}
    for argument in unparsed_arguments:
        subparser_name, argument = get_subparser_from_argument(argument, subparsers)
        if subparser_name:
            unparsed_arguments_dict.setdefault(subparser_name, []).append(argument)

    # Parse the arguments for each subparser and return the result
    parsed_arguments_dict = {}
    for subparser_name, unparsed_arguments in unparsed_arguments_dict.items():
        try:
            parsed_arguments = subparsers[subparser_name].parse_known_args(unparsed_arguments)
        except SystemExit:
            # Raise error if parsing fails
            raise ValueError(f"Failed to parse arguments for subparser {subparser_name}")
        parsed_arguments_dict[subparser_name] = parsed_arguments

    # Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    #   arguments, a list of remaining arguments not claimed by any subparser)
    return parsed_arguments_dict, unparsed_arguments_dict

def parse_subparser_arguments(unparsed_arguments, subparsers):
    """
