def vertex3tuple(vertices):
    '''
    Given a list of vertices, return a list of 3-tuples where each 3-tuple contains the vertex and the two points on either side of it.
    '''
    result = []
    for vertex in vertices:
        try:
            before = vertices[vertices.index(vertex) - 1]
            after = vertices[(vertices.index(vertex) + 1) % len(vertices)]
            result.append((vertex, before, after))
        except IndexError:
            pass
    return result

def vertex3tuple(vertices):
    """Return 3 points for each vertex of the polygon. This will include the vertex and the 2 points on both sides of the vertex.

    Args:
        vertices (list): A list of Point objects representing the vertices of a polygon.

    Returns:
        list: A list of 3-tuples, where each 3-tuple contains the vertex and the 2 points on both sides of the vertex.

    """
    try:
        return self._vertex3tuple
    except AttributeError:
        pass
    self._vertex3tuple = [
        (vertices[i], vertices[(i + 1) % len(vertices)], vertices[(i + 2) % len(vertices)])
        for i in range(len(vertices))
    ]
    return self._vertex3tuple

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    base = len(alphabet)

    # Special case for zero
    if number == 0:
        return alphabet[0]

    # Get the significant digits
    significant_digits = []
    for i in range(1, len(alphabet)):
        if number >= i:
            significant_digits.append(i)

    # Get the rest of the digits
    rest = []
    for i in range(len(significant_digits), len(alphabet)):
        if number >= i * base ** (len(significant_digits)):
            rest.append(i)

    # Pad the output with zeros
    if padding is not None and len(significant_digits) < padding:
        significant_digits += [0] * (padding - len(significant_digits))
    if padding is not None and len(rest) < padding:
        rest += [0] * (padding - len(rest))

    # Construct the output string
    output = ""
    for i in significant_digits:
        output += alphabet[i]
    for i in rest:
        output += alphabet[i]

    return output

def int_to_string(number, alphabet, padding=None):
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    base = len(alphabet)
    number = abs(number)
    if padding is not None:
        result = ["0"] * padding
    else:
        result = []
    while number > 0:
        result.append(alphabet[number % base])
        number //= base
    if result:
        result.reverse()
    else:
        result.append("0")
    if number < 0:
        result.append("-")
    return "".join(result)

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if number < 0:
        raise ValueError("number cannot be negative")
    if padding is not None and padding < 0:
        raise ValueError("padding cannot be negative")

    if padding is not None:
        output = [alphabet[number % len(alphabet)]]
        number //= len(alphabet)
        while number > 0:
            output.append(alphabet[number % len(alphabet)])
            number //= len(alphabet)
        output.reverse()
        result = "".join(output)
        if len(result) < padding:
            return "0" * (padding - len(result)) + result
        return result
    else:
        output = []
        while number > 0:
            output.append(alphabet[number % len(alphabet)])
            number //= len(alphabet)
        output.reverse()
        return "".join(output)

