def split(s, platform='this'):
    """
    Multi-platform variant of shlex.split() for command-line splitting.

    platform: 'this' = auto from current platform;
              '1' = POSIX;
              '0' = Windows/CMD
              (other values reserved)
    """
    if platform == 'this':
        if os.name == 'nt':
            platform = '0'
        else:
            platform = '1'

    re_split_pattern = r' "((?:[^"\\]|\\.)*)" | \'((?:[^\'\\]|\\.)*)\' | (\\S+) '
    if platform == '1':
        re_split_pattern = re.compile(re_split_pattern, flags=re.VERBOSE)
    else:
        re_split_pattern = re.compile(re_split_pattern, flags=(re.VERBOSE | re.IGNORECASE))

    return re_split_pattern.split(s)

def split(s, platform='this'):
    """
    Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if platform == 'this':
        if sys.platform.startswith('win'):
            platform = 0
        else:
            platform = 1

    if platform == 1:
        # POSIX
        return re.split(r'("(\\[^\s"]+|[^"])+?")|(\'(\\[^\s\']+|[^\'])+\'|[^\s]+)', s)
    else:
        # Windows/CMD
        return re.split(r'(("[^"]+")|(\'[^\']+\')|[^\\s\'][^\s"\']*)', s)

    raise ValueError("Invalid platform value: {}".format(platform))

def split(s, platform='this'):
    """
    Multi-platform variant of shlex.split() for command-line splitting.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if platform == 'this':
        if sys.platform == 'win32':
            platform = 0
        else:
            platform = 1
    if platform == 0:
        # Windows/CMD
        pattern = r'("[^"]*"|' + r"'[^']*'|(?:\\.|[^\\\s\w])+|[\w]+" + r")+"
    else:
        # POSIX
        pattern = r'("[^"]*"|' + r"'[^']*'|(?:\\.|[^\\\s])+|[\w]+" + r")+"
    return re.findall(pattern, s)

def split(s, platform='this'):
    """
    Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    # Detect platform
    if platform == 'this':
        platform = 'POSIX' if os.name == 'posix' else 'WINDOWS'

    # Split with REGEX
    if platform == 'POSIX':
        return re.split(r'"([^"]*)"', s)
    elif platform == 'WINDOWS':
        return re.split(r'(\S+)', s)

def addignored(ignored):
    '''
    Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma.
    :param ignored:
    :return: str
    '''
    cmd = ['git', 'ls-files', '--ignored']
    output = subprocess.check_output(cmd).decode('utf-8').splitlines()
    filtered = []
    for line in output:
