def parse_frequency(frequency):
    """
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    """
    if frequency is None or frequency.lower() == "always":
        return None
    m = re.match(r'^(\d+)\s*(second|second|seconds|minute|minutes|hour|hours|day|days|week|weeks|month|months|year|years)$', frequency)
    if not m:
        raise ValueError(f'Invalid frequency: "{frequency}"')
    amount = int(m.group(1))
    unit = m.group(2)
    if unit == "second" or unit == "seconds":
        return datetime.timedelta(seconds=amount)
    elif unit == "minute" or unit == "minutes":
        return datetime.timedelta(minutes=amount)
    elif unit == "hour" or unit == "hours":
        return datetime.timedelta(hours=amount)
    elif unit == "day" or unit == "days":
        return datetime.timedelta(days=amount)
    elif unit == "week" or unit == "weeks":
        return datetime.timedelta(weeks=amount)
    elif unit == "month" or unit == "months":
        return datetime.timedelta(days=amount * 30)
    elif unit == "year" or unit == "years":
        return datetime.timedelta(days=amount * 365)
    else:
        raise ValueError(f'Invalid frequency: "{frequency}"')

