def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """
    Call the given command(s).

    :param commands: the command(s) to run
    :type commands: list[str]

    :param args: the arguments to pass to the command(s)
    :type args: list[str]

    :param cwd: the current working directory to run the command(s) from, defaults to None
    :type cwd: str, optional

    :param verbose: whether to display output from the command(s), defaults to False
    :type verbose: bool, optional

    :param hide_stderr: whether to hide stderr output from the command(s), defaults to False
    :type hide_stderr: bool, optional

    :param env: the environment variables to set for the command(s), defaults to None
    :type env: dict[str, str], optional

    :raises subprocess.CalledProcessError: if the command(s) return a non-zero exit code
    """
    if verbose:
        print("Running command:", " ".join(commands), "with arguments:", " ".join(args))

    if cwd:
        os.chdir(cwd)

    if env:
        os.environ.update(env)

    try:
        process = subprocess.Popen(commands, args, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        output, error = process.communicate()

        if process.returncode != 0:
            msg = "Command {} failed with exit code {}\n".format(commands, process.returncode)
            msg += "STDOUT:\n{}\n\nSTDERR:\n{}".format(output.decode("utf-8"), error.decode("utf-8"))
            raise subprocess.CalledProcessError(process.returncode, commands, msg)

        if verbose:
            print("Command finished with exit code:", process.returncode)
            print("STDOUT:\n", output.decode("utf-8"))
            print("STDERR:\n", error.decode("utf-8"))

        if hide_stderr and not error:
            return output.decode("utf-8")
        else:
            return output.decode("utf-8"), error.decode("utf-8")
    finally:
        if env:
            for key, value in env.items():
                del os.environ[key]

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """
    Call the given command(s).

    :param commands: the commands to run
    :type commands: list
    :param args: the arguments to pass to the commands
    :type args: list
    :param cwd: the working directory for the command
    :type cwd: str
    :param verbose: whether to print the commands and their output
    :type verbose: bool
    :param hide_stderr: whether to hide the output from the errors
    :type hide_stderr: bool
    :param env: the environment variables to set for the command
    :type env: dict
    """
    if not isinstance(commands, list):
        commands = [commands]
    for command in commands:
        if verbose:
            print(f"Executing command: {command}")
        if not hide_stderr:
            kwargs = {"stdout": subprocess.PIPE, "stderr": subprocess.PIPE}
        else:
            kwargs = {"stdout": subprocess.PIPE}
        if cwd is not None:
            kwargs["cwd"] = cwd
        if env is not None:
            kwargs["env"] = env
        p = subprocess.Popen(command, *args, **kwargs)
        if verbose and not hide_stderr:
            for line in p.stderr.readlines():
                print(f"Error: {line.decode().strip()}")
        if not verbose:
            p.stderr = None
        for line in p.stdout.readlines():
            print(line.decode().strip())
        p.wait()

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    if not isinstance(commands, list):
        raise ValueError("The 'commands' parameter must be a list of commands.")

    if verbose:
        print("Running command:", commands)

    if env is not None:
        if not isinstance(env, dict):
            raise ValueError("The 'env' parameter must be a dictionary.")
        proc = subprocess.Popen(commands, args, cwd=cwd, env=env)
    else:
        proc = subprocess.Popen(commands, args, cwd=cwd)

    (output, error) = proc.communicate()

    if verbose:
        print("Output:", output)

    if not hide_stderr:
        print("Error:", error)

    return output, error

