    """Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors."""
    # Initialize the dictionary to store the parsed configurations and the list to store the parse errors
    configurations = {}
    errors = []

    # Iterate over the configuration filenames
    for config_filename in config_filenames:
        # Try loading the configuration file using the specified overrides and resolving environment variables
        try:
            with open(config_filename, 'r') as f:
                config = yaml.safe_load(f.read())
        except FileNotFoundError:
            # The configuration file does not exist, add an error to the list
            errors.append(logging.LogRecord('ERROR', None, None, None, f'File not found: {config_filename}'))

        else:
            # The configuration file exists, try parsing it using the specified overrides and resolving environment variables
            try:
                with open(config_filename, 'r') as f:
                    config = yaml.safe_load(f.read())
            except yaml.scanner.ScannerError as e:
                # The configuration file contains parse errors, add an error to the list
                errors.append(logging.LogRecord('ERROR', None, None, None, f'Error parsing {config_filename}: {e}'))

            else:
                # The configuration file parsed successfully, add it to the dictionary of configurations
                configurations[config_filename] = config

    return configurations, errors

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.

    :param config_filenames: sequence of configuration filenames
    :param overrides: optional dict of configuration overrides
    :param resolve_env: boolean indicating whether to resolve environment variables in configuration files
    :return: tuple of dict of configurations and list of parse errors
    """
    configs = {}
    errors = []

    if not overrides:
        overrides = {}

    for config_filename in config_filenames:
        try:
            with open(config_filename) as f:
                config_data = yaml.safe_load(f)
        except IOError as e:
            errors.append(e)
            continue
        except yaml.YAMLError as e:
            errors.append(e)
            continue

        config = resolver.resolve(config_data, overrides, resolve_env)

        if not isinstance(config, dict):
            errors.append(f"Config file {config_filename} does not contain a dictionary")
            continue

        configs[config_filename] = config

    return configs, errors

