def from_ticks(cls, ticks, tz=None):
    if not (0 <= ticks < 86400000000000):
        raise ValueError("ticks is out of bounds (0 <= ticks < 86400000000000)")
    time = datetime.combine(date.today(), time.min)
    time = time.replace(tzinfo=tz) if tz else time
    return time.fromtimestamp(ticks / 1000000)

def protocol_handlers(protocol_version=None):
    """ Return a dictionary of available Bolt protocol handlers, keyed by version tuple. If an explicit protocol version is provided, the dictionary will contain either zero or one items, depending on whether that version is supported. If no protocol version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """
    if protocol_version is not None and not isinstance(protocol_version, tuple):
        raise TypeError("Protocol version must be passed in a tuple")

    handlers = {}
    for version in cls.PROTOCOL_VERSIONS:
        if protocol_version is None or version == protocol_version:
            handlers[version] = cls.BoltHandler
    return handlers

def protocol_handlers(cls, protocol_version=None):
    """ Return a dictionary of available Bolt protocol handlers,
        keyed by version tuple. If an explicit protocol version is
        provided, the dictionary will contain either zero or one items,
        depending on whether that version is supported. If no protocol
        version is provided, all available versions will be returned.

        :param protocol_version: tuple identifying a specific protocol
            version (e.g. (3, 5)) or None
        :return: dictionary of version tuple to handler class for all
            relevant and supported protocol versions
        :raise TypeError: if protocol version is not passed in a tuple
    """

    # If an explicit protocol version is provided, just check if it's supported
    if protocol_version is not None:
        if not isinstance(protocol_version, tuple):
            raise TypeError('protocol version must be a tuple')
        supported_version = protocol_version in cls.SUPPORTED_PROTOCOL_VERSIONS
        if supported_version:
            return {protocol_version: cls.PROTOCOL_HANDLERS[protocol_version]}
        else:
            return {}

    # Otherwise, return all supported versions
    return {version: cls.PROTOCOL_HANDLERS[version] for version in cls.SUPPORTED_PROTOCOL_VERSIONS}

def protocol_handlers(protocol_version=None):
    """Return a dictionary of available Bolt protocol handlers, keyed by version tuple. If an explicit protocol version is provided, the dictionary will contain either zero or one items, depending on whether that version is supported. If no protocol version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple"""
    if protocol_version is not None and not isinstance(protocol_version, tuple):
        raise TypeError('Protocol version must be passed in a tuple')

    handlers = {}
    for major, minor in PROTOCOL_VERSIONS:
        if protocol_version is None or protocol_version == (major, minor):
            handlers[(major, minor)] = get_protocol_handler(major, minor)
    return handlers

def from_raw_values(cls, values):
    """Create a Bookmarks object from a list of raw bookmark string values.

    You should not need to use this method unless you want to deserialize
    bookmarks.

    :param values: ASCII string values (raw bookmarks)
    :type values: Iterable[str]
    :returns: Bookmarks object
    """
    bookmarks = []
    for value in values:
        if isinstance(value, str):
            bookmarks.append(Bookmark.from_raw_string(value))
        elif isinstance(value, dict):
            bookmarks.append(Bookmark.from_dict(value))
        elif isinstance(value, Bookmark):
            bookmarks.append(value)
        else:
            raise ValueError(f"Unable to convert {value!r} to a Bookmark object.")

    return cls(bookmarks)

def _get_seq_with_type(seq, bufsize=None):
    """
    Returns a (sequence, type) pair.
    Sequence is derived from *seq* (or is *seq*, if that is of a sequence type).
    """
    seq_type = type(seq)
    if isinstance(seq, list):
        seq = seq
    elif isinstance(seq, str):
        seq = list(seq)
        seq_type = type(seq)
    else:
        raise TypeError("Invalid input type")
    return (seq, seq_type)

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    if isinstance(seq, str):
        return (seq, type(seq))
    elif isinstance(seq, bytes):
        return (seq, type(seq))
    elif isinstance(seq, (list, tuple)):
        return (seq, type(seq))
    elif isinstance(seq, (collections.Iterable, characters.Sequence)):
        return (seq, type(seq))
    elif bufsize is not None and hasattr(seq, "__iter__"):
        return seq.__iter__(), type(seq.__next__())
    else:
        return (seq, type(seq))

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    # If seq is already a sequence type, return it as-is
    if isinstance(seq, (list, tuple, bytes, bytearray)):
        return (seq, type(seq))

    # Otherwise, create a new list from seq
    seq_list = list(seq)

    # Return the list as the sequence and type(list) as the type
    return (seq_list, type(seq_list))

def _get_seq_with_type(seq, bufsize=None):
    """
    Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    # Check to see if *seq* is already a sequence
    if isinstance(seq, (list, tuple, set, map)):
        return (seq, type(seq))

    # If not, try to create a list buffer from *seq* with a size of *bufsize*
    # If *bufsize* is None, then create the largest list buffer needed to fit all elements
    try:
        if bufsize:
            buf = list(seq)[:bufsize]
        else:
            buf = list(seq)
    except TypeError:
        # *seq* is an unintensional iterable, so we can't slice it directly
        # Convert it to a list buffer and fallthrough to the next clause
        buf = list(seq)

    # If *buf* is now a list, then it was the originally seq argument and we are done
    if isinstance(buf, list):
        return (seq, type(seq))

    # If we have tried to convert *seq* to a list buffer and all has failed
    # then we fallback to only returning the input sequence as is
    return (seq, type(seq))

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    if is_sequence(seq):
        return (seq, type(seq))
    else:
        return (list(seq), type(list))

def _verify(iface, candidate, tentative=False, vtype=None):
    if not tentative:
        # Check if candidate claims to implement the interface
        if not iface.providedBy(candidate):
            raise zope.interface.Invalid("Candidate does not claim to implement the interface")

    # Check if candidate defines required methods
    for method in iface.names():
        if method not in dir(candidate):
            raise zope.interface.Invalid(f"Candidate does not define required method {method!r}")

    # Check if candidate defines required attributes
    for name in iface.names():
        if name not in candidate.__dict__:
            raise zope.interface.Invalid(f"Candidate does not define required attribute {name!r}")

    # Check if candidate methods and attributes have correct signature
    for name in iface.names():
        func = getattr(candidate, name)
        sig = iface[name]
        bound = sig.bind(func, None)
        bound.apply_defaults()
        missing, extra = bound.signature.parameters.keys()
        if missing or extra:
            if missing:
                missing = ", ".join(f"'{n}'" for n in missing)
                raise zope.interface.Invalid(f"Candidate method {name!r} missing {missing}")
            if extra:
                extra = ", ".join(f"'{n}'" for n in extra)
                raise zope.interface.Invalid(f"Candidate method {name!r} has extra argument {extra}")

    return True

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    if not isinstance(candidate, iface) and tentative:
        return False
    return isinstance(candidate, iface)

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    try:
        if tentative:
            return candidate in iface.__bases__
        else:
            return issubclass(candidate, iface)
    except TypeError:
        return False

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    if not tentative:
        # If the interface is invalid, immediately raise an error
        if not isinstance(iface, Interface):
            raise InvalidArgumentApplicationError('Invalid interface type')
        if not isinstance(candidate, type(iface)):
            raise InvalidArgumentApplicationError('Invalid candidate type')

    # Check if the candidate class provides all required methods
    for method in iface.__abstractmethods__:
        if not method in candidate.__dict__.keys():
            raise InvalidArgumentApplicationError(
                f'Candidate does not implement required method {method}'
            )

    # Check if the candidate class has the correct return types/values for each method
    for method, annotation in iface.__annotations__.items():
        if not method in candidate.__annotations__.keys():
            continue
        candidate_ann = candidate.__annotations__[method]
        if not issubclass(candidate_ann, annotation):
            raise InvalidArgumentApplicationError(
                f'Candidate return type for method {method} is not '
                f'compatible with interface annotation'
            )

    return candidate

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    if not hasattr(candidate, iface):
        raise AttributeError(f"The candidate does not have the required attribute {iface}")
    if tentative:
        return getattr(candidate, iface)
    if not callable(getattr(candidate, iface)):
        raise TypeError(f"The attribute {iface} is not callable.")
    return candidate

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    # Sanity check the arguments passed in
    if not isinstance(iface, type):
        raise InvalidArgumentApplicationError("%s is not a class type" % iface)
    if not isinstance(candidate, type):
        raise InvalidArgumentApplicationError("%s is not a class type" % candidate)

    if tentative:
        try:
            getattr(candidate, "implements")
        except AttributeError:
            return False

        # Use the candidate's implements method to check if it provides iface
        return iface in candidate.implements(exact=True)

    # Check that the candidate inherits from iface
    if not issubclass(candidate, iface):
        return False

    # Check that the candidate implements all of iface's methods
    iface_methods = set(iface.__dict__.keys()) - set(["__doc__", "__module__"])
    candidate_methods = set(candidate.__dict__.keys()) - set(["__doc__", "__module__"])

    return iface_methods.issubset(candidate_methods)

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__

    :param bases: the metaclasses to combine
    :param explicit_mc: an optional explicit __metaclass__ to use
    :return: the determined metaclass
    """
    if explicit_mc is not None:
        # An explicit __metaclass__ was provided, so use it
        return explicit_mc
    else:
        # No explicit __metaclass__ was provided, so combine the bases
        return _combineMetaclasses(bases)

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if bases and not bases[0].__name__ == 'object':
        implicit = bases[0].__class__
    else:
        implicit = object
    if explicit_mc:
        return explicit_mc
    else:
        return implicit

def determineMetaclass(bases, explicit_mc=None):
    """
    Determine metaclass from 1+ bases and optional explicit __metaclass__

    :param bases: A sequence of base classes
    :param explicit_mc: An optional explicit metaclass
    :return: The metaclass to be used for the new class
    """
    if explicit_mc is not None:
        return explicit_mc

    metaclasses = []
    for base in bases:
        try:
            for baseobj in base.infer(context=context):
                if isinstance(baseobj, ClassDef) and baseobj.hide:
                    metaclasses.append(baseobj._metaclass)
                    break
        except exceptions.InferenceError:
            pass

    return next(node for node in metaclasses if node is not util.Uninferable) if metaclasses else None

def determineMetaclass(bases, explicit_mc=None):
    if not bases:
        return None
    elif explicit_mc:
        return explicit_mc
    else:
        for base in bases:
            if hasattr(base, '__metaclass__'):
                return base.__metaclass__
        return type(bases[0])

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__

    :param bases: the bases of the class
    :param explicit_mc: the explicit metaclass, if any
    :return: the determined metaclass
    """
    if explicit_mc is not None:
        return explicit_mc
    else:
        for base in bases:
            if isinstance(base, type):
                return base.__class__
        return object

def pop(self, key, default=None):
    """
    D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    if key not in self:
        if default is not None:
            return default
        raise KeyError(key)
    for map in [self._pb.IntMap, self._pb.FloatMap, self._pb.StringMap,
                self._pb.BoolMap]:
        if key in map.keys():
            return map.pop(key)

def pop(self, key, default=__marker):
    """
    D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """

    # Check if the key exists in the dictionary
    if key in self:
        # If the key exists, remove it from the dictionary and return the value
        return self.pop(key)
    else:
        # If the key does not exist, check if a default value was provided
        if default is not __marker:
            # If a default value was provided, return it
            return default
        else:
            # If no default value was provided, raise a KeyError
            raise KeyError(key)

def pop(self, key, default=None):
    """Remove specified key and return the corresponding value.
    If key is not found, default is returned if given, otherwise KeyError is raised.

    The :func:`pop` method is used to remove specified keys from a dictionary.
    Args:
    - key: The key which should be removed from the dictionary
    - default: The default value to return if no value is found
    Returns:
    - The corresponding value from the key if it was found, otherwise default
    """
    if key not in self:
        if default is not None:
            return default
        raise KeyError(key)
    for map in [self._pb.IntMap, self._pb.FloatMap, self._pb.StringMap,
                    self._pb.BoolMap]:
        if key in map.keys():
            return map.pop(key)

def popitem(self):
    """Remove and return the (key, value) pair least frequently used."""
    try:
        # find the least frequently used key
        least_frequent = min(self.items(), key=lambda x: self.get_freq(x))
        # remove the key and return its value
        self.pop(least_frequent)
        return (least_frequent, self[least_frequent])
    except KeyError:
        raise KeyError("dictator is empty")

