def popitem(self):
    """Remove and return a random `(key, value)` pair."""
    if len(self) == 0:
        raise KeyError("list is empty")
    i = randint(0, len(self) - 1)
    node = self._table[i]
    self._find_lt(node.key)
    value = node.val
    self._remove(node)
    return (node.key, value)

def popitem(self):
        """Remove and return a random `(key, value)` pair.

        This method raises a `KeyError` if the random key cannot be popped."""
        node = random.choice(self._head[2])
        if node is self._tail:
            raise KeyError('list is empty')
        self._find_lt(node[0])
        self._remove(node)
        return (node[0], node[1])

def _create_in_regex(self) -> Pattern:
    """
    Create the in-style parameter regular expression.

    Returns the in-style parameter regular expression (:class:`re.Pattern`).
    """

    return re.compile(r'(?:^|\W)in:(.*?),', flags=re.IGNORECASE | re.DOTALL)

def _create_in_regex(self) -> Pattern:
    """
    Create the in-style parameter regular expression.

    Returns the in-style parameter regular expression (:class:`re.Pattern`).
    """
    return re.compile(r"(?:\s+in\s+)(\$?)(.*?)(\(?\$)(?:\))")

def _create_in_regex(self) -> Pattern:
    """
    Create the in-style parameter regular expression.

    Returns the in-style parameter regular expression (:class:`re.Pattern`).
    """

    return re.compile(r"(?:\s+in\s+)(.*)")

def _create_in_regex(self) -> Pattern:
    """
    Create the in-style parameter regular expression.

    Returns the in-style parameter regular expression (:class:`re.Pattern`).
    """
    expression = ""
    for i, parameter in enumerate(self.parameters):
        if i > 0:
            expression += "|"
        expression += "(?P<prm_{}>{})".format(parameter, parameter)
    return re.compile(expression, flags=re.U)

def _create_in_regex(self) -> Pattern:
    "Create the in-style parameter regular expression."
    return re.compile(r'^URL.*VALUE.*KEY', re.MULTILINE)

