def identify_request(request: RequestType) -> bool:
    """Try to identify whether this is a Matrix request"""
    if not request:
        return False
    if request.META.get('CONTENT_TYPE') == 'application/json' and re.match(r'^/rooms/\w+/send/\w+$', request.path):
        return True
    if request.method == 'POST' and request.path == '/sendToDevice' and request.content_type == 'application/json':
        return True
    if request.method == 'POST' and request.path == '/send' and request.content_type == 'application/json':
        return True
    if request.method == 'GET' and request.path == '/_matrix/client/versions':
        return True
    return False

