def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    tags = set()
    for line in text.splitlines():
        matches = re.finditer(r'\B#\w+', line)
        for match in matches:
            tag = line[match.start():match.end()]
            if replacer is not None:
                tag = replacer(tag)
            tags.add(tag)
    return tags, text

def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    # type: (str, callable) -> Tuple[Set, str]
    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    tags = set()
    state = 'normal'
    tag_start = 0
    replaced_text = ''

    for i, char in enumerate(text):
        if char == '`':
            state = 'code' if state == 'normal' else 'normal'
        elif char == '#' and state == 'normal':
            tag_start = i
        elif char == '\n' and state == 'normal':
            tag = text[tag_start + 1:i].strip()
            if tag:
                tags.add(tag)
                replaced_text += f'#{tag}\n'
        elif state == 'replaced' and char in ' \n':
            state = 'normal'

        if state == 'replaced':
            replaced_text += char

        if state == 'normal' and char == '#':
            if replacer:
                tag = text[i + 1:].split(' ', 1)[0].strip()
                if tag:
                    tag_replacement = replacer(tag)
                    replaced_text += tag_replacement
                    state = 'replaced'

    return tags, replaced_text

def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    tags = set()
    original_text = text
    # Keep track of code blocks to avoid matching tags inside them
    code_blocks = []
    for line in text.splitlines():
        if line.strip().startswith('```'):
            code_blocks.append(not code_blocks[-1] if len(code_blocks) > 0 else True)
        for tag in TAG_RE.findall(line):
            if not any(tag in block for block in code_blocks):
                tags.add(tag)
    if replacer:
        text = re.sub(TAG_RE, lambda m: replacer(m.group(0)), text)
    return tags, original_text

def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    tags = set()
    new_text = ''
    editing = False
    for line in text.split('\n'):
        if editing:
            new_text += line + '\n'
        else:
            new_text += line
        if not editing and line.strip().startswith('```'):
            editing = True
        if editing and line.strip().startswith('```'):
            editing = False
        if not editing and replacer:
            line = replacer(line)
        for tag in line.split():
            if tag.startswith('#') and not tag.startswith('##'):
                tags.add(tag[1:])
    return tags, new_text

