def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    if len(tag) < 2 or len(tag) > 64:
        return False
    if not tag.isalnum():
        return False
    if not (tag[0].isalpha() or tag[0] == '_'):
        return False
    if tag.islower():
        return True
    if tag.isupper():
        return False
    if tag.isdigit():
        return False
    return True

