def verify_relayable_signature(public_key, doc, signature):
    signature_node = doc.find('Signature')
    signed_info_node = signature_node.find('SignedInfo')
    signed_reference_nodes = signed_info_node.findall('Reference')
    signed_reference_strings = []
    for signed_reference_node in signed_reference_nodes:
        signed_info_uri = signed_reference_node.get('URI')
        signed_value = signed_reference_node.find('Transforms').find('Transform').get('Algorithm')
        if signed_info_uri != '#id' or signed_value != 'http://www.w3.org/2000/09/xmldsig#enveloped-signature':
            return False

        signed_reference_text_nodes = signed_reference_node.findall('Transforms').find('Transform').find('DigestValue')
        for signed_reference_text_node in signed_reference_text_nodes:
            signed_reference_strings.append(signed_reference_text_node.text.strip())

    signed_reference_string = ''.join(signed_reference_strings)
    return public_key.verify(base64.b64decode(signed_reference_string), signature)

def verify_relayable_signature(public_key, doc, signature):
    """
    Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    """
    if not public_key or not doc or not signature:
        raise ValueError("Invalid parameters to the verify_relayable_signature method")

    # Verify that the signature is valid
    signature_verified = False
    try:
        signature_verified = rsa.verify(doc, signature, public_key)
    except rsa.pkcs1.VerificationError:
        signature_verified = False

    if not signature_verified:
        raise ValueError("The signer of the message is not trusted")

    # Verify that the timestamp is not too old
    current_ts = datetime.datetime.now()
    ts_element = doc.find(".//{%s}Timestamp" % NS_TBFD)
    ts = datetime.datetime.strptime(ts_element.text, "%Y-%m-%dT%H:%M:%S")
    age = current_ts - ts

    if age > datetime.timedelta(minutes=15):
        raise ValueError("The message is too old")

    # Verify that the RelayState is valid
    relay_state = doc.find(".//{%s}RelayState" % NS_TBFD)
    if relay_state is None:
        raise ValueError("The RelayState is missing")

    if relay_state.text is None or relay_state.text.strip() == "":
        raise ValueError("The RelayState is empty")

    try:
        relay_state_url = urlparse(relay_state.text.strip())
    except ValueError:
        raise ValueError("The RelayState is invalid")

    # Verify that the destination is valid
    destination = doc.find(".//{%s}Destination" % NS_TBFD)
    if destination is None:
        raise ValueError("The Destination is missing")

    if destination.text is None or destination.text.strip() == "":
        raise ValueError("The Destination is empty")

    try:
        destination_url = urlparse(destination.text.strip())
    except ValueError:
        raise ValueError("The Destination is invalid")

    # Verify that the message is for the expected SharedProofEndpoint
    sp_endpoint = doc.find(".//{%s}SharedProofEndpoint" % NS_TBFD)
    if sp_endpoint is None:
        raise ValueError("The SharedProofEndpoint is missing")

    if sp_endpoint.text.strip() != destination_url.netloc:
        raise ValueError("The SharedProofEndpoint is incorrect")

def parse_diaspora_webfinger(document: str) -> Dict:
    try:
        return json.loads(document)
    except json.JSONDecodeError:
        xrd = xrd.parse_xml(document)
        if xrd.name == "XRD":
            return {
                "links": [Link(rel=rel, href=link) for rel, link in xrd.links],
                "aliases": xrd.aliases,
            }
        else:
            raise ValueError("Invalid webfinger document")

def parse_diaspora_webfinger(document: str) -> Dict:
    """Parse Diaspora webfinger, either in JSON format (new) or XRD (old)."""

    # Try parsing the document as JSON, if it fails, assume it's XRD
    try:
        data = json.loads(document)
    except json.JSONDecodeError:
        data = {
            "subject_uri": document["uri"],
            "links": document["links"],
            "properties": document["properties"],
        }

    return data

def parse_diaspora_webfinger(document: str) -> Dict:
    json_data = json.loads(document)
    webfinger = json_data.get("webfinger")
    if webfinger:
        # old format
        hcard_url = webfinger.get("link", {}).get("href")
        if hcard_url is None:
            # handle case where hcard_url is not present
            # ...
        return {"hcard_url": hcard_url, "profile_url": webfinger.get("profile_url")}
    else:
        # new format
        hcard_url = json_data.get("links", [{}])[0].get("href")
        if hcard_url is None:
            # handle case where hcard_url is not present
            # ...
        return {"hcard_url": hcard_url, "profile_url": json_data.get("links", [{}])[0].get("profile_url")}

