def dict_insert(dic, val, key, *keys):
    """
    Insert a value into a nested dictionary with the given keys.

    If any of the keys in the chain do not exist, the method will create
    them and insert the value.

    :param dic: The dictionary to insert the value into.
    :param val: The value to insert.
    :param key: The first key in the chain of keys that will store the value.
    :param keys: The subkeys in the key chain.
    """
    if len(keys) > 0:
        if key not in dic:
            dic[key] = {}
        dict_insert(dic[key], val, *keys)
    else:
        dic[key] = val

