def validate_from_content(spec_content):
    # Load the spec file as a dictionary
    spec = yaml.safe_load(spec_content)

    # Check that all required fields are present
    for field in ['short_name', 'version', 'language', 'description', 'authors']:
        if field not in spec:
            raise IRValidatorException(f'Mandatory field "{field}" is missing from spec.')

    # Check that the spec version is valid
    language = spec["language"]
    if language not in SUPPORTED_LANGUAGES:
        raise IRValidatorException(f'Spec language {language} is not supported.')

    # Check that the dependencies are valid
    if 'dependencies' in spec and len(spec['dependencies']) > 0:
        for dependency in spec['dependencies']:
            if 'name' not in dependency or 'version' not in dependency:
                raise IRValidatorException('Invalid dependency format in spec.')

    # Check that the benchmarks are valid
    if 'benchmarks' in spec and len(spec['benchmarks']) > 0:
        for benchmark in spec['benchmarks']:
            if 'name' not in benchmark or 'version' not in benchmark:
                raise IRValidatorException('Invalid benchmark format in spec.')

    # Check that the results directory is valid
    if 'results_dir' in spec and len(spec['results_dir']) == 0:
        raise IRValidatorException('Results directory is empty.')

    # Check that the license is valid
    if 'license' not in spec or len(spec['license']) == 0:
        raise IRValidatorException('License is missing.')

    # Check that the implementation details are valid
    if 'implementation' not in spec or len(spec['implementation']) == 0:
        raise IRValidatorException('Implementation details are missing.')

    # Return the loaded spec file as a dictionary
    return spec

