def validate_from_file(yaml_file=None):
    """
    Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """

    if not yaml_file:
        raise ValueError("yaml_file argument must be supplied")

    with open(yaml_file, 'r') as f:
        data = yaml.load(f)

    if not data:
        raise IRValidatorException("No data found in the file.")

    if not data.get('name'):
        raise IRValidatorException("Name field is required in the data.")

    if not data.get('version'):
        raise IRValidatorException("Version field is required in the data.")

    if not data.get('description'):
        raise IRValidatorException("Description field is required in the data.")

    return data

def validate_from_file(yaml_file=None):
