    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """

    if not yaml_file:
        raise LookupError("yaml_file argument must be supplied")

    try:
        with open(yaml_file, 'r') as f:
            data = yaml.safe_load(f)
    except yaml.YAMLError as e:
        raise IRValidatorException(f"There was a problem parsing the YAML file: {e}")

    required_fields = ["name", "version", "implementation", "protocols"]

    for field in required_fields:
        if field not in data:
            raise IRValidatorException(f"Field '{field}' is missing in the YAML file")

    return data

