        """
        Resolve arguments' values from the spec and other sources.

        Returns:
            dict: A dictionary containing the resolved argument values.
        """
        defaults = {}
        for arg in self.args:
            # 1. Check if argument name is specified in spec.
            if arg.name in self.spec:
                # 2. If yes, set the argument's value from spec.
                defaults[arg.name] = self.spec[arg.name]
            else:
                # 3. Check if argument has a default value set.
                if arg.has_default():
                    # 4. If yes, set the argument's value to its default.
                    defaults[arg.name] = arg.get_default()
                else:
                    # 5. If no, set the argument's value to None.
                    defaults[arg.name] = None
        return defaults

