def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources.

    Returns:
        dict: A dictionary with the resolved argument values.
    """
    defaults = {}
    for arg in self.args:
        if not isinstance(arg, _BaseOpt):
            raise ValueError('Unable to resolve value for non-Option type')

        try:
            value = self.spec.get_default_value(arg.name)
        except KeyError:
            value = None

        # if there is no default set in the spec, check if the
        # argument has a default value set in the function definition
        if value is None and not isinstance(arg.default, NoDefault):
            value = arg.default

        # if we have a dict option, check if the spec has a default
        # for its scheme and use it if available
        if isinstance(arg, DictOption) and arg.scheme:
            try:
                value = self.spec.get_default_value(arg.scheme().name)
            except KeyError:
                pass

        defaults[arg.name] = value

    return defaults

