def get_conditionally_required_args(command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    conditional_required_args = []
    for arg in options_spec:
        if "required_when" in arg:
            required = False
            for condition in arg["required_when"]:
                if condition in args:
                    required = True
                    break
            if required:
                conditional_required_args.append(arg["name"])
    return conditional_required_args

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when`` condition
    """
    required_args = []

    for option in options_spec:
        if "required_when" not in option:
            continue

        required_for_option = option["required_when"]
        if required_for_option not in args:
            continue

        required_for_value = args[required_for_option]
        if required_for_value not in option["values"]:
            continue

        if option["name"] not in args:
            required_args.append(option["name"])

    return required_args

