def validate_min_max_args(args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    for arg in args:
        if arg["type"] == "Integer":
            if arg["min"] is not None and arg["max"] is not None:
                if not (arg["min"] <= arg["value"] <= arg["max"]):
                    raise ValueError(
                        f"Value of {arg['name']} argument must be between minimum and maximum values"
                    )
            elif arg["min"] is not None:
                if not (arg["min"] <= arg["value"]):
                    raise ValueError(
                        f"Value of {arg['name']} argument must be greater than or equal to minimum value"
                    )
            elif arg["max"] is not None:
                if not (arg["value"] <= arg["max"]):
                    raise ValueError(
                        f"Value of {arg['name']} argument must be less than or equal to maximum value"
                    )
        else:
            raise TypeError(
                f"Argument {arg['name']} must have type Integer"
            )

def validate_min_max_args(args):
    """
    Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """

    # Iterate over the arguments and check if their values are between the minimum and maximum values.
    for arg in args:
        # Get the minimum and maximum values for the argument.
        min_val, max_val = arg.get("min_val", arg.get("max_val"))

        # Check if the argument value is between the minimum and maximum values.
        if min_val and max_val:
            if arg.value < min_val or arg.value > max_val:
                raise ValueError(f"Argument value for {arg.name} is not between the minimum and maximum values")
        # Check if the argument value is equal to the minimum or maximum value.
        elif min_val:
            if arg.value < min_val:
                raise ValueError(f"Argument value for {arg.name} is less than the minimum value")
        elif max_val:
            if arg.value > max_val:
                raise ValueError(f"Argument value for {arg.name} is greater than the maximum value")

    # If none of the arguments have a minimum or maximum value, return.
    if all(not arg.get("min_val") and not arg.get("max_val") for arg in args):
        return None

    # Otherwise, all arguments have a minimum and maximum value.
    return args

def validate_min_max_args(args):
    """
    Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """

    if "min" in args and "max" in args:
        if args["min"] >= args["max"]:
            raise ValueError("'min' cannot be greater than or equal to 'max'")
        if len(args["values"]) != len(args["min"]) or len(args["values"]) != len(args["max"]):
            raise ValueError("'values' should have the same length as 'min' and 'max'")
        for value, min_val, max_val in zip(args["values"], args["min"], args["max"]):
            if value < min_val or value > max_val:
                raise ValueError("value is not within the allowed range")

    elif "range" in args:
        if len(args["values"]) != len(args["range"]):
            raise ValueError("'values' should have the same length as 'range'")
        for value, range_val in zip(args["values"], args["range"]):
            if value < range_val[0] or value > range_val[1]:
                raise ValueError("value is not within the allowed range")

    else:
        raise ValueError("'min' or 'max' or 'range' must be provided")

    return args

def create_json_type(self, subcommand, type_name, option_name, spec_option):
    """Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    return {
        type_name: {
            option_name: {
                "type": "json",
                "spec": spec_option
            }
        }
    }

def get_nested_custom_and_control_args(args):
    """
    Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    control_args = {}
    nested_args = {}
    for arg in args:
        if arg.startswith('_'):
            control_args[arg] = args[arg]
        else:
            nested_args[arg] = args[arg]
    return (control_args, nested_args)

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    nested_args = {}
    custom_args = {}
    control_args = {}
    for arg in args:
        if arg.startswith("-"):
            control_args[arg] = args.pop(arg)
        elif arg.startswith("--nested"):
            key, value = arg.split("=")
            nested_args[key.replace("--nested", "")] = value
        elif arg.startswith("--custom"):
            key, value = arg.split("=")
            custom_args[key.replace("--custom", "")] = value
    return control_args, nested_args, custom_args

