def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if extra_vars is None:
        return vars_dict

    for extra_var in extra_vars:
        if isinstance(extra_var, dict):
            if not isinstance(vars_dict, dict):
                raise ValueError("Unable to merge: Dictionnary expected")
            vars_dict.update(extra_var)
        elif isinstance(extra_var, list):
            if not isinstance(vars_dict, list):
                raise ValueError("Unable to merge: List expected")
            vars_dict += extra_var
        else:
            raise ValueError("Unable to merge: Dictionary or list expected")

    return vars_dict

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend `vars_dict` with `extra-vars`

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if extra_vars is None:
        return vars_dict
    elif not isinstance(extra_vars, list):
        raise ValueError("Unable to merge: List expected")
    else:
        for key in extra_vars:
            if key not in vars_dict:
                vars_dict[str(key)] = extra_vars[key]
            else:
                if isinstance(vars_dict[key], list) and isinstance(extra_vars[key], list):
                    vars_dict[key].extend(extra_vars[key])
                elif isinstance(vars_dict[key], dict) and isinstance(extra_vars[key], dict):
                    merge_extra_vars(vars_dict[key], extra_vars[key])
                else:
                    vars_dict[key] = extra_vars[key]

    return vars_dict

def merge_extra_vars(vars_dict, extra_vars=None):
    if extra_vars is None:
        return vars_dict

    if not isinstance(extra_vars, list):
        raise ValueError("'extra-vars' must be a list")

    for extra_var in extra_vars:
        if not isinstance(extra_var, dict):
            raise ValueError("Element in 'extra-vars' must be a dictionary")

        for key, value in extra_var.items():
            if key not in vars_dict:
                vars_dict[key] = value
            else:
                current_value = vars_dict[key]
                if isinstance(current_value, dict) and isinstance(value, dict):
                    merge_extra_vars(current_value, value)
                else:
                    vars_dict[key] = value

    return vars_dict

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``"""
    if not vars_dict and not extra_vars:
        return vars_dict

    if extra_vars is not None:
        new_vars_dict = vars_dict.copy()
        new_vars_dict.update(extra_vars)
        return new_vars_dict
    else:
        return vars_dict

def merge_extra_vars(vars_dict, extra_vars=None):
    if extra_vars is None:
        return vars_dict
    if not isinstance(extra_vars, list):
        raise ValueError("Unable to merge: List expected")
    for var in extra_vars:
        if not isinstance(var, dict):
            raise ValueError("Unable to merge: Dictionnary expected")
        if set(var.keys()).isdisjoint(set(vars_dict.keys())):
            vars_dict.update(var)
        else:
            for key in var:
                if key not in vars_dict:
                    vars_dict[key] = var[key]
                elif isinstance(vars_dict[key], dict):
                    self.merge_extra_vars(vars_dict[key], var[key])
    return vars_dict

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    # Validate and parse input arguments
    if extra_vars is not None and not isinstance(extra_vars, dict):
        raise TypeError("Extra variables must be a dictionary")
    if ansible_args is not None and not isinstance(ansible_args, dict):
        raise TypeError("Ansible arguments must be a dictionary")

    # Build ansible command
    ansible_cmd = ["ansible-playbook", "-i", ir_workspace.ansible_host_file,
                   "-b", "-v", str(verbose)]

    # Add extra variables
    if extra_vars is not None:
        ansible_cmd.extend(["-e", ",".join(f"{k}={v}" for k, v in extra_vars.items())])

    # Add ansible arguments
    if ansible_args is not None:
        ansible_cmd.extend(["-e", ",".join(f"{k}={v}" for k, v in ansible_args.items())])

    # Add playbook path
    ansible_cmd.append(playbook_path)

    # Execute ansible command
    return subprocess.run(ansible_cmd, check=True, capture_output=True)

def _convert_non_cli_args(self, parser_name, values_dict):
    """
    Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """

    # handle each argument individually
    for key, value in values_dict.items():
        # check if the argument value is a list
        if isinstance(value, list):
            # if the list contains only one item, then convert it to a string
            if len(value) == 1:
                values_dict[key] = str(value[0])
            # otherwise, convert the list to a space-separated string
            else:
                values_dict[key] = " ".join(value)
        # check if the argument value is a bool
        elif isinstance(value, bool):
            # if the value is True, then convert it to "true"
            if value:
                values_dict[key] = "true"
            # otherwise, convert it to "false"
            else:
                values_dict[key] = "false"
        # if the argument value is a string or a number, then do nothing
        else:
            pass

    # return the converted arguments dictionary
    return values_dict

def _convert_non_cli_args(parser_name, values_dict):
    """
    1. Convert arguments to correct types by modifying the values_dict param.
    2. By default, all the values are strings.
    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """

    args_spec = self.get_args_spec(parser_name)
    if args_spec:
        for arg in args_spec:
            if arg in values_dict:
                arg_type = args_spec[arg]["type"]
                if arg_type and arg_type != str:
                    try:
                        values_dict[arg] = arg_type(values_dict[arg])
                    except ValueError:
                        pass
    return values_dict

def get_plugin_spec_flatten_dict(plugin_dir):
    """
    Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    spec_dict = {}
    with open(os.path.join(plugin_dir, "spec.json"), "r") as spec_file:
        spec = json.load(spec_file)
        for key, value in spec.items():
            if isinstance(value, dict):
                for subkey, subvalue in value.items():
                    spec_dict[f"{key}.{subkey}"] = subvalue
            else:
                spec_dict[key] = value
    return spec_dict

